div.script:
document.addEventListener('DOMContentLoaded', function () {
    const cardView = document.getElementById('cardView');
    const tableView = document.getElementById('tableView');
    const btnCard = document.getElementById('btnCardView');
    const btnTable = document.getElementById('btnTableView');

    function showCard() {
        cardView.style.display = 'block';
        tableView.style.display = 'none';
        btnCard.classList.add('active');
        btnTable.classList.remove('active');
        localStorage.setItem('wsr_view', 'card');
    }

    function showTable() {
        cardView.style.display = 'none';
        tableView.style.display = 'block';
        btnTable.classList.add('active');
        btnCard.classList.remove('active');
        localStorage.setItem('wsr_view', 'table');
    }

    btnCard.addEventListener('click', showCard);
    btnTable.addEventListener('click', showTable);

    if (localStorage.getItem('wsr_view') === 'table') {
        showTable();
    } else {
        showCard();
    }
});

t.script:
(function () {

async function loadPickupPoints(partnerId) {

const sel = document.getElementById('pickup_point_ids');
if (!sel) return;

// reset dropdown
sel.innerHTML = 'Select recognised address';
if (!partnerId) return;

try {
const res = await fetch('/my/waste/pickup_points', {
method: 'POST',
credentials: 'same-origin',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ partner_id: partnerId })
});

const rows = await res.json();

(rows || []).forEach(pp => {
const opt = document.createElement('option');
opt.value = pp.id;
opt.textContent = pp.name;
sel.appendChild(opt);
});

} catch (err) {
console.error('Failed to load pickup points:', err);
}
}

document.addEventListener('DOMContentLoaded', function () {
const clientSel = document.getElementById('client_partner_id');
if (!clientSel) return;

clientSel.addEventListener('change', function () {
loadPickupPoints(this.value);
});

// initial load
});

})();

function wmzEditPickupPoint(btn) {
const ppId = btn.dataset.id;
const currentName = btn.dataset.name;

const newName = prompt("Edit address name:", currentName);
if (!newName || newName.trim() === currentName) return;

fetch(`/my/waste/pickup_points/${ppId}/edit`, {
method: 'POST',
headers: {
'Content-Type': 'application/json',
'X-Requested-With': 'XMLHttpRequest'
},
body: JSON.stringify({ name: newName.trim() })
})
.then(r => r.json())
.then(resp => {
if (resp.error) {
alert(resp.error);
} else {
location.reload();
}
});
}

function wmzDeletePickupPoint(btn) {
const ppId = btn.dataset.id;

if (!confirm("Remove this collection address?")) return;

fetch(`/my/waste/pickup_points/${ppId}/archive`, {
method: 'POST',
headers: {
'X-Requested-With': 'XMLHttpRequest'
}
})
.then(r => r.json())
.then(resp => {
if (resp.error) {
alert(resp.error);
} else {
location.reload();
}
});
}

$(document).ready(function () {
$('#pickup_point_id').select2({
placeholder: "Select collection addresses",
width: '100%',
closeOnSelect: false
});
});

(function () {

const selected = new Map(); // id → name

function updateHiddenField() {
const input = document.getElementById('pickup_point_ids');
input.value = Array.from(selected.keys()).join(',');
}

function removeBadge(id) {
selected.delete(id);
document.getElementById('pp_badge_' + id)?.remove();
updateHiddenField();
}

function addBadge(id, name) {
if (selected.has(id)) return;

selected.set(id, name);

const container = document.getElementById('pickup_point_badges');

const badge = document.createElement('span');
badge.className = 'badge bg-primary d-flex align-items-center';
badge.id = 'pp_badge_' + id;

badge.innerHTML = `
${name}

`;

badge.querySelector('button').onclick = () => removeBadge(id);

container.appendChild(badge);

updateHiddenField();
}

document.addEventListener('DOMContentLoaded', function () {

const select = document.getElementById('pickup_point_select');

select.addEventListener('change', function () {
const id = this.value;
const name = this.options[this.selectedIndex].text;

if (id) {
addBadge(id, name);
this.value = ''; // reset dropdown
}
});

});

})();

(function () {

async function jsonCall(url, payload) {
const res = await fetch(url, {
method: 'POST',
headers: {'Content-Type': 'application/json'},
body: JSON.stringify(payload || {})
});
return await res.json();
}

function hideModalSafe(modalId) {
const modalEl = document.getElementById(modalId);
if (!modalEl) return;

// ✅ If bootstrap is available, use it
if (window.bootstrap && window.bootstrap.Modal) {
const modal = window.bootstrap.Modal.getOrCreateInstance(modalEl);
modal.hide();
return;
}

// ✅ Fallback (no bootstrap global)
modalEl.classList.remove('show');
modalEl.style.display = 'none';
modalEl.setAttribute('aria-hidden', 'true');
document.body.classList.remove('modal-open');
document.querySelectorAll('.modal-backdrop').forEach(b => b.remove());
}

async function addPickupPoint(ev) {
if (ev) ev.preventDefault();

const partnerId = document.getElementById('client_partner_id')?.value;
const name = document.getElementById('pp_name')?.value?.trim();

const errBox = document.getElementById('pp_error');
if (errBox) {
errBox.classList.add('d-none');
errBox.textContent = '';
}

if (!partnerId) {
if (errBox) { errBox.textContent = "Please select a client/company first.";
errBox.classList.remove('d-none'); }
return;
}
if (!name) {
if (errBox) { errBox.textContent = "Address Name is required."; errBox.classList.remove('d-none'); }
return;
}





const resp = await jsonCall('/my/waste/pickup_points/create', {
name: name
});


if (resp && resp.error) {
if (errBox) { errBox.textContent = resp.error; errBox.classList.remove('d-none'); }
return;
}

// ✅ Add to dropdown + select it
const sel = document.getElementById('pickup_point_id');
if (sel) {






const opt = document.createElement('option');
opt.value = resp.id;
opt.textContent = resp.name;

// mark selected
opt.selected = true;

sel.appendChild(opt);


}

// reset input
const inp = document.getElementById('pp_name');
if (inp) inp.value = '';

hideModalSafe('addPickupPointModal');
}

document.addEventListener('DOMContentLoaded', function () {
const btn = document.getElementById('pp_save_btn');
if (btn) btn.addEventListener('click', addPickupPoint);
});

})();

(function () {

function toggleSize() {
const sel = document.getElementById('container_type_id');
const binGroup = document.getElementById('bin_type_group');
const tankGroup = document.getElementById('tank_volume_group');
if (!sel || !binGroup || !tankGroup) return;

const opt = sel.options[sel.selectedIndex];
const kind = (opt && opt.dataset && opt.dataset.kind) ? opt.dataset.kind : '';

// We detect by name. Make sure your container.type names contain "bin" or "tank"
const isBin = kind.includes('bin');
const isTank = kind.includes('tank');

if (isBin) {
binGroup.classList.remove('d-none');
tankGroup.classList.add('d-none');
} else if (isTank) {
tankGroup.classList.remove('d-none');
binGroup.classList.add('d-none');
} else {
binGroup.classList.add('d-none');
tankGroup.classList.add('d-none');
}
}

document.addEventListener('DOMContentLoaded', function () {
const sel = document.getElementById('container_type_id');
if (!sel) return;
sel.addEventListener('change', toggleSize);
toggleSize();
});

})();

(function () {
document.addEventListener('DOMContentLoaded', function () {
// No auto-open; the modal opens via data-bs-toggle="modal" links.
});
})();

(function () {
function setupSignaturePad(canvasId, clearBtnId, changedLabelId, previewBtnId) {
var canvas = document.getElementById(canvasId);
if (!canvas || !window.SignaturePad) {
return null;
}

function resizeCanvas() {
var ratio = window.devicePixelRatio || 1;
var rect = canvas.getBoundingClientRect();
canvas.width = rect.width * ratio;
canvas.height = 150 * ratio;
var ctx = canvas.getContext('2d');
ctx.scale(ratio, ratio);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

var pad = new window.SignaturePad(canvas, {
backgroundColor: 'rgb(255,255,255)'
});

var clearBtn = document.getElementById(clearBtnId);
var changedLabel = document.getElementById(changedLabelId);
var previewBtn = document.getElementById(previewBtnId);

// Mark as changed when user draws
pad.onEnd = function () {
if (changedLabel) {
changedLabel.classList.remove('d-none');
}
if (previewBtn) {
previewBtn.disabled = false;
}
};

if (clearBtn) {
clearBtn.addEventListener('click', function (ev) {
ev.preventDefault();
pad.clear();
if (changedLabel) {
changedLabel.classList.add('d-none');
}
if (previewBtn) {
previewBtn.disabled = true;
}
});
}
return pad;
}

document.addEventListener('DOMContentLoaded', function () {
// --- SIGNATURES ---
var driverPad = setupSignaturePad(
'driverSignaturePad',
'driverSignatureClear',
'driverSignatureChangedLabel',
'driverSignaturePreviewBtn'
);
var customerPad = setupSignaturePad(
'customerSignaturePad',
'customerSignatureClear',
'customerSignatureChangedLabel',
'customerSignaturePreviewBtn'
);

var form = document.querySelector('form.o_portal_waste_worksheet_form');
if (form) {
form.addEventListener('submit', function () {
var driverField = document.getElementById('driver_signature_data');
var customerField = document.getElementById('service_provider_signature_data');

if (driverPad && !driverPad.isEmpty()) {
driverField.value = driverPad.toDataURL('image/png');
} else if (driverField) {
driverField.value = '';
}

if (customerPad && !customerPad.isEmpty()) {
customerField.value = customerPad.toDataURL('image/png');
} else if (customerField) {
customerField.value = '';
}
});
}

// Signature preview modal
var sigModal = document.getElementById('signatureZoomModal');
var sigImg = document.getElementById('signatureZoomModalImg');

var driverPrevBtn = document.getElementById('driverSignaturePreviewBtn');
if (driverPrevBtn && driverPad && sigModal && sigImg) {
driverPrevBtn.addEventListener('click', function () {
if (!driverPad.isEmpty()) {
sigImg.src = driverPad.toDataURL('image/png');
var modal = bootstrap.Modal.getOrCreateInstance(sigModal);
modal.show();
}
});
}

var customerPrevBtn = document.getElementById('customerSignaturePreviewBtn');
if (customerPrevBtn && customerPad && sigModal && sigImg) {
customerPrevBtn.addEventListener('click', function () {
if (!customerPad.isEmpty()) {
sigImg.src = customerPad.toDataURL('image/png');
var modal = bootstrap.Modal.getOrCreateInstance(sigModal);
modal.show();
}
});
}

// --- PHOTO ZOOM (existing) ---
var zoomLinks = document.querySelectorAll('.ws-photo-thumb');
var zoomImg = document.getElementById('photoZoomModalImg');
var zoomCaption = document.getElementById('photoZoomModalCaption');

zoomLinks.forEach(function (link) {
link.addEventListener('click', function () {
var url = this.getAttribute('data-img-url');
var title = this.getAttribute('data-img-title') || 'Photo';

if (zoomImg) {
zoomImg.src = url;
}
if (zoomCaption) {
zoomCaption.textContent = title;
}
});
});

// --- DOCUMENT NEW FILE HINTS ---
var docInputs = document.querySelectorAll('.doc-file-input');
docInputs.forEach(function (input) {
input.addEventListener('change', function () {
var hintId = input.id.replace('_input', '_new_file_hint');
var hint = document.getElementById(hintId);
if (!hint) {
return;
}
var span = hint.querySelector('.doc-new-file-name');
if (input.files && input.files.length) {
if (span) {
span.textContent = input.files[0].name;
}
hint.classList.remove('d-none');
} else {
hint.classList.add('d-none');
}
});
});

// Clear document change (reset file input)
var clearBtns = document.querySelectorAll('.doc-clear-change');
clearBtns.forEach(function (btn) {
btn.addEventListener('click', function () {
var inputId = btn.getAttribute('data-input-id');
var hintId = btn.getAttribute('data-hint-id');
var inp = document.getElementById(inputId);
var hint = document.getElementById(hintId);

if (inp) {
inp.value = '';
}
if (hint) {
hint.classList.add('d-none');
}
});
});
});
})();
